script:
(function () {
  'use strict';
  // ---- Federal Direct Loan fixed-payment plan rules (checked 2026; sources below) ----
  // Loans first disbursed BEFORE July 1, 2026 (studentaid.gov servicer pages, 34 CFR 685.208):
  //   Standard: fixed payments over 10 years, minimum payment $50.
  //   Graduated: up to 10 years; payments start lower and rise, usually every two years; no payment may be
  //     more than three times any other (34 CFR 685.208).
  //   Extended: 25 years, fixed or graduated; needs more than $30,000 in outstanding Direct Loans and all
  //     loans disbursed before July 1, 2026.
  // Loans first disbursed ON OR AFTER July 1, 2026 (One Big Beautiful Bill Act; Edfinancial/studentaid.gov):
  //   Tiered Standard: fixed payments; term by total outstanding Direct Loan principal:
  //     under $25,000 = 10 years; $25,000-$49,999 = 15; $50,000-$99,999 = 20; $100,000 or more = 25.
  // Income-driven plans (including RAP) are not modelled: they depend on income and family size.
  var STANDARD_MIN_PAYMENT = 50;
  var EXTENDED_MIN_BALANCE = 30000;
  var TIERS = [{ below: 25000, years: 10 }, { below: 50000, years: 15 }, { below: 100000, years: 20 }, { below: Infinity, years: 25 }];
  var GRAD_STEP_MONTHS = 24;
  var GRAD_MAX_RATIO = 3;
  // ---------------------------------------------------------------------------------------------------
  // Maths: monthly rate i = r/12 (servicers accrue simple daily interest; monthly accrual is a close estimate).
  //   Fixed plan: PMT = B * i / (1 - (1 + i)^-n).
  //   Graduated plan (our estimate; servicers set the exact steps): payment level k (0-based, one level per
  //   24 months) = P1 * g^k. For a given g the payoff condition gives P1 = B(1+i)^n / sum_k g^level(k) (1+i)^(n-k).
  //   We use the lowest first payment the rules allow: P1 = monthly interest (B*i) with g found by bisection,
  //   unless that would make the last level more than 3x the first, in which case g = 3^(1/(levels-1)).
  // Verified in Node (scratchpad w3loans/tests): $30,000 at 6.8% over 10 years = $345.24/mo, total interest
  //   $11,428.92 (closed form; matches a published calculator's default result); every graduated schedule
  //   ends at a $0 balance, starts at no less than the first month's interest and its last payment is at
  //   most 3x its first; tiers: $24,999 -> 10 years, $25,000 -> 15, $99,999 -> 20, $100,000 -> 25;
  //   $3,000 at 5% on standard pays the $50 minimum and finishes early; 0% rate, blank and negative input
  //   never show NaN; extended rows say "not available" at $30,000 or less.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var last = null;

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(principal, i, n) {
    if (n <= 0 || principal <= 0) return 0;
    if (i === 0) return principal / n;
    return principal * i / (1 - Math.pow(1 + i, -n));
  }

  function tierYears(balance) {
    for (var k = 0; k < TIERS.length; k++) if (balance < TIERS[k].below) return TIERS[k].years;
    return 25;
  }

  // First payment for growth factor g so that the graduated schedule repays B in n months.
  function gradFirst(B, i, n, g) {
    var s = 0;
    for (var k = 1; k <= n; k++) s += Math.pow(g, Math.floor((k - 1) / GRAD_STEP_MONTHS)) * Math.pow(1 + i, n - k);
    return B * Math.pow(1 + i, n) / s;
  }

  function graduated(B, i, n) {
    var levels = Math.ceil(n / GRAD_STEP_MONTHS);
    var gMax = Math.pow(GRAD_MAX_RATIO, 1 / Math.max(1, levels - 1));
    var floor = B * i, g = gMax;
    if (gradFirst(B, i, n, gMax) < floor) {
      var lo = 1, hi = gMax;
      for (var t = 0; t < 100; t++) {
        var mid = (lo + hi) / 2;
        if (gradFirst(B, i, n, mid) > floor) lo = mid; else hi = mid;
      }
      g = (lo + hi) / 2;
    }
    var p1 = gradFirst(B, i, n, g);
    return function (k) { return p1 * Math.pow(g, Math.floor((k - 1) / GRAD_STEP_MONTHS)); };
  }

  // Pays payAt(k) + extra each month until the balance is gone.
  function simulate(B, i, payAt, extra, maxN) {
    var bal = B, rows = [], totalInterest = 0, totalPaid = 0;
    for (var k = 1; k <= maxN && bal > 0.005; k++) {
      var interest = bal * i;
      var amount = Math.min(payAt(k) + extra, bal + interest);
      bal = bal + interest - amount;
      if (bal < 0.005) bal = 0;
      totalInterest += interest;
      totalPaid += amount;
      rows.push({ n: k, amount: amount, interest: interest, principal: amount - interest, balance: bal });
    }
    return { rows: rows, totalInterest: totalInterest, totalPaid: totalPaid, first: rows.length ? rows[0].amount : 0,
             top: rows.reduce(function (m, r) { return Math.max(m, r.amount); }, 0) };
  }

  function fixedPlan(B, i, years, minPay) {
    var pmt = Math.max(payment(B, i, years * 12), minPay || 0);
    return function () { return pmt; };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function cell(tr, text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); }

  function clearResults() {
    ['slPayment', 'slInterest', 'slTotal', 'slTime', 'slSaved', 'slFaster'].forEach(function (id) { setText(id, '–'); });
    el('slExtraBox').hidden = true;
    el('slPlans').textContent = '';
    el('slSchedule').textContent = '';
    last = null;
  }

  function renderSchedule() {
    var body = el('slSchedule');
    body.textContent = '';
    if (!last) return;
    var p = 0, intr = 0, paid = 0;
    last.rows.forEach(function (row, idx) {
      p += row.principal; intr += row.interest; paid += row.amount;
      if (row.n % 12 === 0 || idx === last.rows.length - 1) {
        var tr = document.createElement('tr');
        cell(tr, String(Math.ceil(row.n / 12))); cell(tr, money.format(paid)); cell(tr, money.format(p));
        cell(tr, money.format(intr)); cell(tr, money.format(row.balance));
        body.appendChild(tr);
        p = 0; intr = 0; paid = 0;
      }
    });
  }

  function update() {
    var type = el('slType').value;
    el('slTermField').hidden = type !== 'private';
    el('slPlansSection').hidden = type === 'private';
    var balance = read('slBalance'), rate = read('slRate'), term = read('slTerm'), extra = read('slExtra', true), msg = '';
    if (isNaN(balance) || balance <= 0) msg = 'Enter a loan balance greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 40) msg = 'Enter an interest rate from 0% to 40%.';
    else if (type === 'private' && (isNaN(term) || term < 1 || term > 30 || term % 1 !== 0)) msg = 'Enter a repayment term of 1 to 30 whole years.';
    else if (isNaN(extra) || extra < 0) msg = 'The extra monthly payment cannot be negative.';
    var error = el('slError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var i = rate / 100 / 12, mainPlan, mainName;
    if (type === 'pre') { mainPlan = fixedPlan(balance, i, 10, STANDARD_MIN_PAYMENT); mainName = 'Standard plan (10 years)'; }
    else if (type === 'post') { mainPlan = fixedPlan(balance, i, tierYears(balance)); mainName = 'Tiered Standard plan (' + tierYears(balance) + ' years)'; }
    else { mainPlan = fixedPlan(balance, i, term); mainName = 'Your loan (' + term + (term === 1 ? ' year)' : ' years)'); }

    var base = simulate(balance, i, mainPlan, 0, 600);
    var withExtra = simulate(balance, i, mainPlan, extra, 600);
    setText('slPlanName', mainName);
    setText('slPayment', money.format(base.first));
    setText('slInterest', money.format(base.totalInterest));
    setText('slTotal', money.format(base.totalPaid));
    setText('slTime', duration(base.rows.length));
    el('slExtraBox').hidden = !(extra > 0);
    setText('slExtraTime', duration(withExtra.rows.length));
    setText('slSaved', money.format(Math.max(0, base.totalInterest - withExtra.totalInterest)));
    setText('slFaster', duration(Math.max(0, base.rows.length - withExtra.rows.length)));

    var body = el('slPlans');
    body.textContent = '';
    var plans = type === 'pre' ? [
      { name: 'Standard (10 years)', pay: mainPlan, ok: true },
      { name: 'Graduated (10 years, estimate)', pay: graduated(balance, i, 120), ok: true, grad: true },
      { name: 'Extended fixed (25 years)', pay: fixedPlan(balance, i, 25), ok: balance > EXTENDED_MIN_BALANCE },
      { name: 'Extended graduated (25 years, estimate)', pay: graduated(balance, i, 300), ok: balance > EXTENDED_MIN_BALANCE, grad: true }
    ] : [
      { name: 'Tiered Standard (' + tierYears(balance) + ' years)', pay: mainPlan, ok: true },
      { name: 'Paid off in 10 years (your choice)', pay: fixedPlan(balance, i, 10), ok: true }
    ];
    if (type !== 'private') plans.forEach(function (plan) {
      var tr = document.createElement('tr');
      cell(tr, plan.name);
      if (!plan.ok) {
        cell(tr, 'Needs more than ' + money0.format(EXTENDED_MIN_BALANCE) + ' owed'); cell(tr, '–'); cell(tr, '–'); cell(tr, '–');
      } else {
        var s = simulate(balance, i, plan.pay, 0, 600);
        cell(tr, plan.grad ? money.format(s.first) + ' rising to ' + money.format(s.top) : money.format(s.first));
        cell(tr, duration(s.rows.length)); cell(tr, money.format(s.totalInterest)); cell(tr, money.format(s.totalPaid));
      }
      body.appendChild(tr);
    });
    last = { rows: withExtra.rows };
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('slForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
